<?php
/** Independent stage publication and controls on real disposable Nextcloud databases. */
declare(strict_types=1);
require '/var/www/html/lib/base.php';
set_exception_handler(function(\Throwable $e){fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);});
if(!is_file('/test-output/ISOLATED_SYNTHETIC_TEST'))throw new RuntimeException('Synthetic guard missing');
use OCP\Server;
use OCA\Nextgallery\AI\Service\{Metadata,Settings,State,Inventory,Files,Embeddings,ProcessingAdministration};
use OCA\Nextgallery\Controller\{AiAccountController,AiWorkerController};
$n=0;function threeCheck($v,$m){global $n;$n++;if(!$v)throw new RuntimeException($m);}
$users=Server::get(\OCP\IUserManager::class);$session=Server::get(\OCP\IUserSession::class);$settings=Server::get(Settings::class);$state=Server::get(State::class);$meta=Server::get(Metadata::class);$uid='three-pipeline-synthetic';$before=$settings->get();
$u=$users->get($uid)??$users->createUser($uid,'SyntheticThreePipelines2026!');$session->setUser($u);$home=Server::get(\OCP\Files\IRootFolder::class)->getUserFolder($uid);$folder=$home->nodeExists('Synthetic')?$home->get('Synthetic'):$home->newFolder('Synthetic');$one=($folder->nodeExists('ocr-first.png')?$folder->get('ocr-first.png'):$folder->newFile('ocr-first.png',file_get_contents('/samples/dog.png')));$two=($folder->nodeExists('description-first.png')?$folder->get('description-first.png'):$folder->newFile('description-first.png',file_get_contents('/samples/invoice.png')));$meta->reset($uid);$original=hash('sha256',$one->getContent());$settings->saveAccount($uid,['folders'=>['/Synthetic'],'enabled'=>false]);$own=$state->forUser($uid);$own->registerAccount();
$vision=['type'=>'foto','description'=>'SYNTHETICDESCRIPTION','tags'=>['SYNTHETICTAG'],'objects'=>[],'uncertain_details'=>[]];
try{
$publish=function($file,string $kind,array $value)use($meta,$own,$uid){$lock=fopen($own->directory().'/publication.lock','c');flock($lock,LOCK_EX);try{$meta->upsert($uid,Metadata::validate($file->getId(),$file->getEtag(),str_repeat('a',64),str_repeat('b',64),$value,[],$kind),$kind);}finally{flock($lock,LOCK_UN);fclose($lock);}};
$publish($one,'ocr',['ocr'=>['text'=>'SYNTHETICONLYTEXT']]);threeCheck($meta->count($uid,'ocr')===1&&$meta->count($uid,'descriptions')===0,'OCR-only publish not independent');threeCheck(count($meta->search($uid,'SYNTHETICONLYTEXT',0,10))===1,'OCR-only search missing');
$publish($one,'descriptions',['vision'=>$vision]);$publish($two,'descriptions',['vision'=>$vision]);$publish($two,'ocr',['ocr'=>['text'=>'']]);threeCheck($meta->count($uid,'ocr')===2&&$meta->count($uid,'descriptions')===2,'Either publication order lost a stage');
$account=Server::get(AiAccountController::class);$config=$account->config()->getData();threeCheck($config['description_count']===2&&$config['ocr_count']===2,'Account stage counts incorrect');
$files=$account->library('Synthetic')->getData();threeCheck($files['counts']['done']===2&&$files['counts']['ocr_done']===2,'Library stage totals incorrect');threeCheck(count($account->library('Synthetic','all','',0,'all','done')->getData()['files'])===2,'OCR filter missing');
$inventory=Server::get(Inventory::class)->forUser($uid);$page=$inventory->page(0,'ocr');threeCheck(count($page['items'])===2&&$page['items'][0]['analyzed_etag']!==null,'OCR inventory ignores published stage');
foreach(['descriptions','ocr','embeddings'] as $kind){$state->forPipeline($kind)->atomic('service.json',['heartbeat_at'=>time()+1800,'active_user_id'=>null]);$own->forPipeline($kind)->atomic('status.json',['state'=>'paused','stats'=>['done'=>2,'pending'=>1]]);$own->forPipeline($kind)->setControl('pause');}
$embedding=$own->forPipeline('embeddings');$embedding->setControl('start');$embedding->atomic('status.json',['state'=>'running','stats'=>['done'=>0,'pending'=>2]]);$gate=$state->globalLock(false,'embeddings');
try{threeCheck($account->control('start','descriptions')->getStatus()===200,'Running embeddings blocked description start');threeCheck($account->control('start','ocr')->getStatus()===200,'Running embeddings blocked OCR start');threeCheck($own->forPipeline('descriptions')->control()['requested']&&$own->forPipeline('ocr')->control()['requested'],'Independent start requests missing');}finally{State::releaseLock($gate);}
$admin=new ProcessingAdministration($settings,$state,Server::get(Embeddings::class),Server::get(\OCA\Nextgallery\AI\Service\EmbeddingClient::class));$descriptionBefore=$own->forPipeline('descriptions')->control();$embeddingBefore=$embedding->control();$admin->pauseAll('ocr');threeCheck($own->forPipeline('descriptions')->control()===$descriptionBefore&&$embedding->control()===$embeddingBefore,'OCR suspension affected other pipelines');$admin->allowRuns('ocr');
$descGate=$state->globalLock(false,'descriptions');$embGate=$state->globalLock(false,'embeddings');try{$changed=$settings->get();$changed['ocr']['timeout_seconds']-=1;threeCheck($admin->save($changed,'','',false)['changed']===false,'OCR settings blocked by other pipeline gates');}finally{State::releaseLock($descGate);State::releaseLock($embGate);$settings->save($before);}
$meta->reset($uid,'descriptions');threeCheck($meta->count($uid,'descriptions')===0&&$meta->count($uid,'ocr')===2,'Description reset removed OCR');threeCheck(count($meta->search($uid,'SYNTHETICONLYTEXT',0,10))===1,'Description reset removed OCR search');
$publish($one,'descriptions',['vision'=>$vision]);$meta->reset($uid,'ocr');threeCheck($meta->count($uid,'descriptions')===1&&$meta->count($uid,'ocr')===0,'OCR reset removed description');threeCheck(count($meta->search($uid,'SYNTHETICDESCRIPTION',0,10))===1&&count($meta->search($uid,'SYNTHETICONLYTEXT',0,10))===0,'Selective reset left wrong search data');threeCheck(hash('sha256',$one->getContent())===$original,'Original synthetic media modified');
$own->setControl('pause');$embedding->atomic('status.json',['state'=>'paused']);$session->setUser($users->get('synthetic-admin'));
echo "$n real Nextcloud three-pipeline publication/search/model/control/reset assertions passed\n";

}finally{$settings->save($before);$state->setProcessingPaused(false,'ocr');$own->setControl('pause');foreach(['descriptions','ocr','embeddings'] as $kind)$own->forPipeline($kind)->atomic('status.json',['state'=>'paused','stats'=>[]]);$session->setUser($users->get('synthetic-admin'));}
